#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 0;
    }
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1]) {
        printf("BAD_INPUT\n");
        return 0;
    }
    if (n < 0) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }
    if (n == 0) {
        printf("EMPTY\n");
        return 0;
    }
    long long *arr = (long long *) malloc(n * sizeof(long long));
    arr[0] = 1;
    for (int i = 1; i < n; i++) {
        arr[i] = 1;
        for (int j = i - 1; j > 0; j--) {
            arr[j] = arr[j] + arr[j - 1];
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            printf(" ");
        }
        for (int j = 0; j <= i; j++) {
            printf("%lld ", arr[j]);
        }
        printf("\n");
    }
    free(arr);
    return 0;
}
